from django import template
from django.urls import resolve
from django.utils.safestring import mark_safe

register = template.Library()

ACTIVE_CLASSES = "nav-link-active"


@register.simple_tag(takes_context=True)
def is_active(context, url_name):
    """Return the active-state class if the current view name matches url_name."""
    request = context.get("request")
    if not request:
        return ""
    try:
        current = resolve(request.path_info).view_name
    except Exception:
        return ""
    return ACTIVE_CLASSES if current == url_name else ""


@register.simple_tag(takes_context=True)
def is_active_prefix(context, path_prefix):
    """Return the active-state class if the current path starts with path_prefix."""
    request = context.get("request")
    if not request:
        return ""
    return ACTIVE_CLASSES if request.path.startswith(path_prefix) else ""


