@register.simple_tag
def icon(name, css_class="h-5 w-5 shrink-0"):
    path = _ICONS.get(name, "")
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
        f'stroke-width="1.5" stroke="currentColor" class="{css_class}">{path}</svg>'
    )
    return mark_safe(svg)